if (s->async) {
	comedi_buf_alloc(dev, s, 0);
	/*
	 * Wait for any poll waiters to disappear.
	 * POLL_ADD (io_uring) removes itself upon wakeup (signaled earlier).
	 * This prevents UAF if kfree_rcu happens before works run.
	 */
	while (waitqueue_active(&s->async->wait_head))
		schedule_timeout_uninterruptible(1);
	kfree_rcu(s->async, rcu);
}

